    DECLARE @SmsEvents NVARCHAR(MAX) = N'{"onSelectedRow":"","onRowAdded":"function(ctx) {\n    var data = ctx.rowData || {};\n    var s = data.t1_Status;\n    var color = null;\n    if (s == 0 || s === ''0'') color = ''#fff3cd'';\n    else if (s == 1 || s === ''1'') color = ''#cfe2ff'';\n    else if (s == 2 || s === ''2'') color = ''#d1e7dd'';\n    else if (s == 3 || s === ''3'') color = ''#75b798'';\n    else if (s == 4 || s === ''4'') color = ''#f1aeb5'';\n    else if (s == 5 || s === ''5'') color = ''#fecba1'';\n    else if (s == 6 || s === ''6'') color = ''#dee2e6'';\n    else if (s == 7 || s === ''7'') color = ''#ea868f'';\n    if (!color || !ctx.table) return;\n    var colIdx = -1;\n    ctx.table.columns().every(function (i) {\n        if (this.dataSrc() === ''_rowNumber'') colIdx = i;\n    });\n    var node = colIdx >= 0 ? ctx.table.cell(ctx.$row, colIdx).node() : ctx.$row.find(''td'').get(0);\n    if (node) $(node).css(''background-color'', color);\n}"}';
    DECLARE @SmsId BIGINT;

    IF ISJSON(@SmsQueryJson) <> 1 OR ISJSON(@SmsColumnsJson) <> 1 OR ISJSON(@SmsActions) <> 1 OR ISJSON(@SmsButtons) <> 1 OR ISJSON(@SmsEvents) <> 1
        THROW 51660, N'JSON نمایه System_SmsMessage_List معتبر نیست.', 1;

    IF EXISTS (SELECT 1 FROM [system].[SavedQuery] WHERE Name = @SmsName)
    BEGIN
        UPDATE [system].[SavedQuery]
        SET Title = @SmsTitle, QueryJson = @SmsQueryJson, ColumnsJson = @SmsColumnsJson,
            EntityFullName = @SmsEntity, Mode = 1, Type = 1, ActionOptions = @SmsActions,
            CustomActionButtonsJson = @SmsButtons, EventScriptsJson = @SmsEvents, DiagramJson = N'{}',
            ModifiedById = 1, ModifiedByName = @SeedUser, ModifiedDateMiladiDateTime = @Now,
            ModifiedDateShamsiDateTime = @NowShamsi, IsActive = 1
        WHERE Name = @SmsName;
        SELECT @SmsId = Id FROM [system].[SavedQuery] WHERE Name = @SmsName;
    END
    ELSE
    BEGIN
        INSERT INTO [system].[SavedQuery]
        (Name, Title, QueryJson, ColumnsJson, DiagramJson, CustomActionButtonsJson, EventScriptsJson,
         Mode, Type, EntityFullName, ActionOptions, CreatedById, ModifiedById, CreatedByName, ModifiedByName,
         CreatedOnMiladiDateTime, CreatedOnShamsiDateTime, ModifiedDateMiladiDateTime, ModifiedDateShamsiDateTime, IsActive)
        VALUES
        (@SmsName, @SmsTitle, @SmsQueryJson, @SmsColumnsJson, N'{}', @SmsButtons, @SmsEvents,
         1, 1, @SmsEntity, @SmsActions, 1, 1, @SeedUser, @SeedUser, @Now, @NowShamsi, @Now, @NowShamsi, 1);
        SET @SmsId = SCOPE_IDENTITY();
    END;

    -- دسترسی نمایه فقط برای نقش admin؛ نقش‌های دیگر از صفحه «گروه‌های کاربری» داده می‌شود.
    INSERT INTO [system].[RoleAccess]
    (Path, ActionAccessType, ActionAccessItemType, EntityName, DisplayName, EntityId, RowId, RoleId,
     CreatedById, ModifiedById, CreatedByName, ModifiedByName,
     CreatedOnMiladiDateTime, CreatedOnShamsiDateTime, ModifiedDateMiladiDateTime, ModifiedDateShamsiDateTime, IsActive)
    SELECT N'dataProfile_' + CAST(@SmsId AS NVARCHAR(20)), 3, 7, @SmsEntityPascal, @SmsTitle, NULL, @SmsId, r.Id,
           1, 1, @SeedUser, @SeedUser, @Now, @NowShamsi, @Now, @NowShamsi, 1
    FROM [system].[Role] r
    WHERE r.Name = N'admin'
      AND NOT EXISTS (SELECT 1 FROM [system].[RoleAccess] ra
                      WHERE ra.RoleId = r.Id AND ra.Path = N'dataProfile_' + CAST(@SmsId AS NVARCHAR(20)) AND ra.ActionAccessType = 3);

    -- ===== System_GeneralSetting_List =====
    DECLARE @GsName NVARCHAR(200) = N'System_GeneralSetting_List';
    DECLARE @GsTitle NVARCHAR(200) = N'تنظیمات عمومی';
    DECLARE @GsEntity NVARCHAR(200) = N'entities.base.generalsetting';
    DECLARE @GsEntityPascal NVARCHAR(200) = N'Entities.Base.GeneralSetting';
    DECLARE @GsQueryJson NVARCHAR(MAX) = N'{"Tables":[],"Relations":[],"Filters":[],"CustomConditions":[],"CustomQuery":"SELECT\n    [t1].[Id] AS [t1_Id],\n    [t1].[SettingKey] AS [t1_SettingKey],\n    [t1].[Title] AS [t1_Title],\n    CASE WHEN [t1].[IsSecret] = 1 THEN CASE WHEN [t1].[SettingValue] IS NULL OR [t1].[SettingValue] = N'''' THEN N''(تنظیم نشده)'' ELSE N''••••••••'' END ELSE LEFT([t1].[SettingValue], 300) END AS [t1_ValueMasked],\n    CASE WHEN [t1].[IsSecret] = 1 THEN N''بله'' ELSE N''خیر'' END AS [t1_IsSecretTitle],\n    [t1].[Description] AS [t1_Description],\n    [t1].[CreatedOnShamsiDateTime] AS [t1_CreatedOnShamsiDateTime],\n    [t1].[ModifiedDateShamsiDateTime] AS [t1_ModifiedDateShamsiDateTime],\n    [t1].[ModifiedByName] AS [t1_ModifiedByName]\nFROM [system].[GeneralSetting] AS [t1]","Parameters":[],"Selects":null}';
    DECLARE @GsColumnsJson NVARCHAR(MAX) = N'[{"TableName":"system.GeneralSetting","ColumnName":"t1_Id","DisplayName":"شناسه","Alliance":"t1_Id","Address":"[t1].[Id]","SystemTypeName":"Long","SelectIndex":0,"Visible":false,"PrimaryKey":true,"SystemType":6,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":80,"Filterable":true,"Sortable":true,"ClassName":""},{"TableName":"system.GeneralSetting","ColumnName":"t1_SettingKey","DisplayName":"کلید","Alliance":"t1_SettingKey","Address":"[t1].[SettingKey]","SystemTypeName":"String","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":0,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":260,"Filterable":true,"Sortable":true,"ClassName":"ltr"},{"TableName":"system.GeneralSetting","ColumnName":"t1_Title","DisplayName":"عنوان","Alliance":"t1_Title","Address":"[t1].[Title]","SystemTypeName":"String","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":0,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":240,"Filterable":true,"Sortable":true,"ClassName":""},{"TableName":"system.GeneralSetting","ColumnName":"t1_ValueMasked","DisplayName":"مقدار","Alliance":"t1_ValueMasked","Address":"CASE WHEN [t1].[IsSecret] = 1 THEN CASE WHEN [t1].[SettingValue] IS NULL OR [t1].[SettingValue] = N'''' THEN N''(تنظیم نشده)'' ELSE N''••••••••'' END ELSE LEFT([t1].[SettingValue], 300) END","SystemTypeName":"String","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":0,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":"function(data, type, row) { if (data == null || data === \"\") return \"\"; if (type !== \"display\") return data; var t = String(data).replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\").replace(/\"/g, \"&quot;\"); return \"<span title=\\\"\" + t + \"\\\" style=\\\"display:inline-block;max-width:420px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;vertical-align:bottom\\\">\" + t + \"</span>\"; }","IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":320,"Filterable":true,"Sortable":true,"ClassName":"ltr"},{"TableName":"system.GeneralSetting","ColumnName":"t1_IsSecretTitle","DisplayName":"محرمانه","Alliance":"t1_IsSecretTitle","Address":"CASE WHEN [t1].[IsSecret] = 1 THEN N''بله'' ELSE N''خیر'' END","SystemTypeName":"String","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":0,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":90,"Filterable":true,"Sortable":true,"ClassName":""},{"TableName":"system.GeneralSetting","ColumnName":"t1_Description","DisplayName":"توضیحات","Alliance":"t1_Description","Address":"[t1].[Description]","SystemTypeName":"String","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":0,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":"function(data, type, row) { if (data == null || data === \"\") return \"\"; if (type !== \"display\") return data; var t = String(data).replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\").replace(/\"/g, \"&quot;\"); return \"<span title=\\\"\" + t + \"\\\" style=\\\"display:inline-block;max-width:420px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;vertical-align:bottom\\\">\" + t + \"</span>\"; }","IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":360,"Filterable":true,"Sortable":true,"ClassName":""},{"TableName":"system.GeneralSetting","ColumnName":"t1_CreatedOnShamsiDateTime","DisplayName":"تاریخ ایجاد","Alliance":"t1_CreatedOnShamsiDateTime","Address":"[t1].[CreatedOnShamsiDateTime]","SystemTypeName":"DateTimeShamsi","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":4,"SortDirection":1,"SortOrder":0,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":150,"Filterable":true,"Sortable":true,"ClassName":""},{"TableName":"system.GeneralSetting","ColumnName":"t1_ModifiedDateShamsiDateTime","DisplayName":"تاریخ ویرایش","Alliance":"t1_ModifiedDateShamsiDateTime","Address":"[t1].[ModifiedDateShamsiDateTime]","SystemTypeName":"DateTimeShamsi","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":4,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":150,"Filterable":true,"Sortable":true,"ClassName":""},{"TableName":"system.GeneralSetting","ColumnName":"t1_ModifiedByName","DisplayName":"ویرایش‌کننده","Alliance":"t1_ModifiedByName","Address":"[t1].[ModifiedByName]","SystemTypeName":"String","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":0,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":150,"Filterable":true,"Sortable":true,"ClassName":""}]';
    DECLARE @GsActions NVARCHAR(MAX) = N'[{"dataActionName":"new","enable":true,"title":"جدید"},{"dataActionName":"edit","enable":true,"title":"ویرایش"},{"dataActionName":"delete","enable":true,"title":"حذف"},{"dataActionName":"exportExcell","enable":true,"title":"خروجی اکسل"}]';
    DECLARE @GsButtons NVARCHAR(MAX) = N'[]';
    DECLARE @GsEvents NVARCHAR(MAX) = N'{"onSelectedRow":"","onRowAdded":""}';
    DECLARE @GsId BIGINT;

    IF ISJSON(@GsQueryJson) <> 1 OR ISJSON(@GsColumnsJson) <> 1 OR ISJSON(@GsActions) <> 1 OR ISJSON(@GsButtons) <> 1 OR ISJSON(@GsEvents) <> 1
        THROW 51660, N'JSON نمایه System_GeneralSetting_List معتبر نیست.', 1;

    IF EXISTS (SELECT 1 FROM [system].[SavedQuery] WHERE Name = @GsName)
    BEGIN
        UPDATE [system].[SavedQuery]
        SET Title = @GsTitle, QueryJson = @GsQueryJson, ColumnsJson = @GsColumnsJson,
            EntityFullName = @GsEntity, Mode = 1, Type = 1, ActionOptions = @GsActions,
            CustomActionButtonsJson = @GsButtons, EventScriptsJson = @GsEvents, DiagramJson = N'{}',
            ModifiedById = 1, ModifiedByName = @SeedUser, ModifiedDateMiladiDateTime = @Now,
            ModifiedDateShamsiDateTime = @NowShamsi, IsActive = 1
        WHERE Name = @GsName;
        SELECT @GsId = Id FROM [system].[SavedQuery] WHERE Name = @GsName;
    END
    ELSE
    BEGIN
        INSERT INTO [system].[SavedQuery]
        (Name, Title, QueryJson, ColumnsJson, DiagramJson, CustomActionButtonsJson, EventScriptsJson,
         Mode, Type, EntityFullName, ActionOptions, CreatedById, ModifiedById, CreatedByName, ModifiedByName,
         CreatedOnMiladiDateTime, CreatedOnShamsiDateTime, ModifiedDateMiladiDateTime, ModifiedDateShamsiDateTime, IsActive)
        VALUES
        (@GsName, @GsTitle, @GsQueryJson, @GsColumnsJson, N'{}', @GsButtons, @GsEvents,
         1, 1, @GsEntity, @GsActions, 1, 1, @SeedUser, @SeedUser, @Now, @NowShamsi, @Now, @NowShamsi, 1);
        SET @GsId = SCOPE_IDENTITY();
    END;

    -- دسترسی نمایه فقط برای نقش admin؛ نقش‌های دیگر از صفحه «گروه‌های کاربری» داده می‌شود.
    INSERT INTO [system].[RoleAccess]
    (Path, ActionAccessType, ActionAccessItemType, EntityName, DisplayName, EntityId, RowId, RoleId,
     CreatedById, ModifiedById, CreatedByName, ModifiedByName,
     CreatedOnMiladiDateTime, CreatedOnShamsiDateTime, ModifiedDateMiladiDateTime, ModifiedDateShamsiDateTime, IsActive)
    SELECT N'dataProfile_' + CAST(@GsId AS NVARCHAR(20)), 3, 7, @GsEntityPascal, @GsTitle, NULL, @GsId, r.Id,
           1, 1, @SeedUser, @SeedUser, @Now, @NowShamsi, @Now, @NowShamsi, 1
    FROM [system].[Role] r
    WHERE r.Name = N'admin'
      AND NOT EXISTS (SELECT 1 FROM [system].[RoleAccess] ra
                      WHERE ra.RoleId = r.Id AND ra.Path = N'dataProfile_' + CAST(@GsId AS NVARCHAR(20)) AND ra.ActionAccessType = 3);

    -- ===== دسترسی صفحه/Api برای admin =====
    INSERT INTO [system].[RoleAccess]
    (Path, ActionAccessType, ActionAccessItemType, EntityName, DisplayName, EntityId, RowId, RoleId,
     CreatedById, ModifiedById, CreatedByName, ModifiedByName,
     CreatedOnMiladiDateTime, CreatedOnShamsiDateTime, ModifiedDateMiladiDateTime, ModifiedDateShamsiDateTime, IsActive)
    SELECT v.Path, v.AType, v.IType,
           CASE WHEN v.Path LIKE N'/panel/system/smsmessage/%' THEN N'Entities.Base.Sms.SmsMessage' ELSE N'Entities.Base.GeneralSetting' END,
           v.Title, NULL, NULL, r.Id, 1, 1, @SeedUser, @SeedUser, @Now, @NowShamsi, @Now, @NowShamsi, 1
    FROM [system].[Role] r
    CROSS JOIN (VALUES
        (N'/panel/system/smsmessage/list', 1, 1, N'لیست پیامک‌ها'),
        (N'/panel/system/smsmessage/detail', 1, 0, N'جزئیات پیامک'),
        (N'/panel/system/smsmessage/fetchdata', 2, 2, N'دریافت اطلاعات پیامک‌ها'),
        (N'/panel/system/smsmessage/resend', 2, 1000, N'ارسال مجدد پیامک'),
        (N'/panel/system/smsmessage/cancel', 2, 1000, N'لغو پیامک'),
        (N'/panel/system/generalsetting/list', 1, 1, N'لیست تنظیمات عمومی'),
        (N'/panel/system/generalsetting/edit', 1, 5, N'ویرایش تنظیم عمومی'),
        (N'/panel/system/generalsetting/new', 1, 4, N'درج تنظیم عمومی'),
        (N'/panel/system/generalsetting/fetchdata', 2, 2, N'دریافت اطلاعات تنظیمات عمومی'),
        (N'/panel/system/generalsetting/save', 2, 3, N'ذخیره تنظیم عمومی'),
        (N'/panel/system/generalsetting/delete', 2, 6, N'حذف تنظیم عمومی')
    ) v(Path, AType, IType, Title)
    WHERE r.Name = N'admin'
      AND NOT EXISTS (SELECT 1 FROM [system].[RoleAccess] ra WHERE ra.RoleId = r.Id AND ra.Path = v.Path AND ra.ActionAccessType = v.AType);

    -- ===== منو: بعد از «لاگ خطاها» در گروه «حقوق دسترسی» =====
    DECLARE @Content NVARCHAR(MAX);
    SELECT @Content = Content FROM [system].[SystemMenu] WHERE Name = N'AllMenus';
    DECLARE @Leaf0 NVARCHAR(MAX) = N'{"text":"پیامک‌ها","icon":"ki-message-text-2 ki-outline","iconColor":"#60A5FA","path":"/panel/system/smsmessage/list","a_attr":{"href":"/panel/system/smsmessage/list"},"data":{"iconColor":"#60A5FA","path":"/panel/system/smsmessage/list"},"children":[]}';
    DECLARE @Leaf1 NVARCHAR(MAX) = N'{"text":"تنظیمات عمومی","icon":"ki-setting-2 ki-outline","iconColor":"#A78BFA","path":"/panel/system/generalsetting/list","a_attr":{"href":"/panel/system/generalsetting/list"},"data":{"iconColor":"#A78BFA","path":"/panel/system/generalsetting/list"},"children":[]}';
    IF @Content IS NOT NULL AND ISJSON(@Content) = 1
       AND JSON_VALUE(@Content, N'$[1].text') = N'حقوق دسترسی'
       AND (CHARINDEX(N'/panel/system/smsmessage/list', @Content) = 0 OR CHARINDEX(N'/panel/system/generalsetting/list', @Content) = 0)
    BEGIN
        DECLARE @Children NVARCHAR(MAX) = JSON_QUERY(@Content, N'$[1].children');
        DECLARE @Rebuilt NVARCHAR(MAX) = N'[';
        DECLARE @n INT = (SELECT COUNT(*) FROM OPENJSON(@Children));
        DECLARE @x INT = 0;
        DECLARE @comma BIT = 0;
        WHILE @x < @n
        BEGIN
            IF @comma = 1 SET @Rebuilt += N',';
            SET @comma = 1;
            SET @Rebuilt += JSON_QUERY(@Children, N'$[' + CAST(@x AS NVARCHAR(10)) + N']');
            IF JSON_VALUE(@Children, N'$[' + CAST(@x AS NVARCHAR(10)) + N'].path') = N'/panel/system/exceptionlog/list'
                SET @Rebuilt += CASE WHEN CHARINDEX(N'/panel/system/smsmessage/list', @Content) = 0 THEN N',' + @Leaf0 ELSE N'' END + CASE WHEN CHARINDEX(N'/panel/system/generalsetting/list', @Content) = 0 THEN N',' + @Leaf1 ELSE N'' END;
            SET @x += 1;
        END
        SET @Rebuilt += N']';
        SET @Content = JSON_MODIFY(@Content, N'$[1].children', JSON_QUERY(@Rebuilt));
        IF @Content IS NULL OR ISJSON(@Content) <> 1
            THROW 51661, N'JSON منو بعد از افزودن پیامک‌ها معتبر نیست.', 1;
        UPDATE [system].[SystemMenu]
        SET Content = @Content, ModifiedById = 1, ModifiedByName = @SeedUser,
            ModifiedDateMiladiDateTime = @Now, ModifiedDateShamsiDateTime = @NowShamsi
        WHERE Name = N'AllMenus';
    END

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    DECLARE @Err NVARCHAR(4000) = ERROR_MESSAGE();
    RAISERROR(@Err, 16, 1);
END CATCH;

SELECT q.Name, JSON_VALUE(j.value, '$.Alliance') AS Alliance, JSON_VALUE(j.value, '$.DisplayName') AS DisplayName
FROM [system].[SavedQuery] q
CROSS APPLY OPENJSON(q.ColumnsJson) j
WHERE q.Name IN (N'System_SmsMessage_List', N'System_GeneralSetting_List');
